"""Community contribution: middle-relay / bridge torrc generation.

Tor has no "DNS node" role — arbitrary DNS queries cannot be relayed. The
community-minded equivalent is a NON-EXIT relay: a middle relay or bridge
carries the network's traffic (including the DNS resolutions that exit relays
perform for clients) without ever exiting plaintext to the internet.

This module will only ever emit ExitPolicy 'reject *:*'. There is no code
path to an exit relay here.
"""

from __future__ import annotations

from dataclasses import dataclass

TORRC_HEADER = """\
# torrc generated by noisyCricket v2 'cricket relay gen'
# Community contribution: {mode} relay. NOT an exit node — ExitPolicy is
# pinned to reject-all below and cannot be overridden by this tool.
"""


class RelayConfigError(ValueError):
    pass


@dataclass
class RelaySpec:
    mode: str = "middle"              # middle | bridge
    nickname: str = "noisycricket"
    contact: str | None = None
    bandwidth_rate: str = "5Mbit"
    or_port: int = 9001
    dir_port: int = 9030
    socks_policy: str = "reject *:*"

    def validate(self) -> None:
        if self.mode not in ("middle", "bridge"):
            raise RelayConfigError(
                f"relay mode '{self.mode}' is not supported — "
                "noisyCricket only runs middle relays or bridges, never exits")
        if not (1024 <= self.or_port <= 65535 and self.or_port != 9050):
            raise RelayConfigError("or_port must be a non-9050 port in 1024-65535")
        if not (0 <= self.dir_port <= 65535 and self.dir_port != 9050):
            raise RelayConfigError("dir_port must be 0 or a non-9050 port in 1-65535")
        if self.dir_port != 0 and self.dir_port == self.or_port:
            raise RelayConfigError("or_port and dir_port must not be identical")
        if not (1 <= len(self.nickname) <= 19):
            raise RelayConfigError("nickname must be 1-19 chars, letters/digits")
        if not all(c.isalnum() for c in self.nickname):
            raise RelayConfigError("nickname must be alphanumeric")


def generate_torrc(spec: RelaySpec) -> str:
    """Emit a non-exit relay torrc. Bridges get bridge-specific lines."""
    spec.validate()
    lines = [
        TORRC_HEADER.format(mode=spec.mode).rstrip(),
        "",
        f"Nickname {spec.nickname}",
    ]
    if spec.contact:
        lines.append(f"ContactInfo {spec.contact}")
    dir_port_line = "DirPort 0" if spec.mode == "bridge" else f"DirPort {spec.dir_port}"
    lines += [
        f"RelayBandwidthRate {spec.bandwidth_rate}",
        f"RelayBandwidthBurst {spec.bandwidth_rate}",
        f"ORPort {spec.or_port}",
        dir_port_line,
        "SocksPort 0",
        "ExitPolicy reject *:*",
        f"SocksPolicy {spec.socks_policy}",
        "",
        "# Safety: publish reachable, non-exit relay",
        "AssumeReachable 0",
    ]
    if spec.mode == "bridge":
        lines += [
            "",
            "# Bridge mode: no descriptor publication to the main directory",
            "BridgeRelay 1",
            "PublishServerDescriptor bridge",
        ]
    else:
        lines += ["", "BridgeRelay 0"]
    # final guard: nothing may enable exiting after our policy line
    lines += ["", "# pinned: this relay exits nothing", "ExitPolicy reject6 *:*"]
    return "\n".join(lines) + "\n"


def warn_if_exit_requested(torrc_text: str) -> list[str]:
    """Defensive: scan a generated torrc for any exit capability.

    Only reject-all policies (v4 and v6) are acceptable on any ExitPolicy line.
    """
    def is_reject_all(line: str) -> bool:
        line = line.lower().replace("reject6", "reject")
        return "accept" not in line and "reject *:*" in line

    warnings = []
    for line in torrc_text.splitlines():
        stripped = line.strip()
        if stripped.startswith("ExitPortObfuscation") or \
           (stripped.startswith("ExitPolicy") and not is_reject_all(stripped)):
            warnings.append(f"refusing exit capability in line: {stripped}")
    return warnings
